def cache_sim(capacity, ttl, ops):
    from collections import OrderedDict

    cache = OrderedDict()  # key -> (value, write_time)
    results = []

    for op in ops:
        kind = op[0]
        t = op[1]
        key = op[2]

        if kind == 'get':
            if key in cache:
                value, write_time = cache[key]
                if t >= write_time + ttl:
                    # expired
                    del cache[key]
                    results.append(-1)
                else:
                    cache.move_to_end(key)
                    results.append(value)
            else:
                results.append(-1)

        elif kind == 'put':
            value = op[3]

            # check if key exists and expired -> remove first
            if key in cache:
                _, write_time = cache[key]
                if t >= write_time + ttl:
                    del cache[key]

            if key in cache:
                # existing, not expired -> update
                cache[key] = (value, t)
                cache.move_to_end(key)
            else:
                # new entry
                if len(cache) >= capacity:
                    cache.popitem(last=False)
                cache[key] = (value, t)
                cache.move_to_end(key)

    return results

